import{az as e,P as l,Q as i,aQ as r}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"面试题/优化/index.md","filePath":"面试题/优化/index.md","lastUpdated":1781716938000}'),t={name:"面试题/优化/index.md"};function n(h,a,o,d,s,c){return l(),i("div",null,[...a[0]||(a[0]=[r('<h2 id="优化介绍" tabindex="-1">优化介绍 <a class="header-anchor" href="#优化介绍" aria-label="Permalink to “优化介绍”">​</a></h2><p>为了保证技术的健全性、稳定性、研发效率、团队水平，优化是需要做取舍的，想要快速地项目节奏，那就用一些项目框架，然后在这个框架的基础进行优化，有了框架的约束则更好维护。如果一味地为了优化而优化则会造成开发进度的损失，在保证开发进度的同时做优化处理是最好的，这种优化被称为“开发习惯”。比如使用框架就是不如原生技术好，但是项目逐渐庞大，原生技术会不如现成框架技术成熟（有已封装好的经过开源社区使用）， 为了赶开发进度而一时不能按照良好的开发习惯去做事情，会逐渐让项目难以维护，此时不如长痛不如短痛牺牲一下过分优化而使用成熟技术</p><ol><li>后续代码维护</li><li>不拖延开发项目进度</li></ol><h2 id="页面渲染速度优化" tabindex="-1">页面渲染速度优化 <a class="header-anchor" href="#页面渲染速度优化" aria-label="Permalink to “页面渲染速度优化”">​</a></h2><h2 id="程序流畅度优化" tabindex="-1">程序流畅度优化 <a class="header-anchor" href="#程序流畅度优化" aria-label="Permalink to “程序流畅度优化”">​</a></h2><h2 id="首屏优化" tabindex="-1">首屏优化 <a class="header-anchor" href="#首屏优化" aria-label="Permalink to “首屏优化”">​</a></h2><h2 id="懒加载" tabindex="-1">懒加载 <a class="header-anchor" href="#懒加载" aria-label="Permalink to “懒加载”">​</a></h2><h2 id="防抖、节流" tabindex="-1">防抖、节流 <a class="header-anchor" href="#防抖、节流" aria-label="Permalink to “防抖、节流”">​</a></h2><h3 id="防抖-debounce" tabindex="-1">防抖（Debounce） <a class="header-anchor" href="#防抖-debounce" aria-label="Permalink to “防抖（Debounce）”">​</a></h3><ul><li>作用 ：在事件触发后，等待一段时间（如 300ms），如果这段时间内事件没有再次触发，才执行函数；<strong>如果在等待时间内事件再次触发，则重新计时</strong>。</li><li>核心思想 ：将多次频繁触发的操作合并为一次执行。</li><li>常见应用场景 ： <ul><li>搜索框输入联想：用户停止输入后才发送请求</li><li>窗口大小调整：窗口调整完成后才重新计算布局</li><li>表单验证：用户输入完成后再进行验证</li></ul></li></ul><h3 id="节流-throttle" tabindex="-1">节流（Throttle） <a class="header-anchor" href="#节流-throttle" aria-label="Permalink to “节流（Throttle）”">​</a></h3><ul><li>作用 ：在一定时间间隔内（如 500ms），只执行一次函数，无论事件触发多少次。</li><li>核心思想 ：控制函数执行的频率，确保在固定时间内只执行一次。</li><li>常见应用场景 ： <ul><li>滚动加载：滚动时每隔一段时间检查一次位置</li><li>按钮点击防重复：短时间内多次点击只执行一次</li><li>鼠标移动事件：每隔一段时间记录一次位置</li></ul></li></ul><h3 id="简单总结" tabindex="-1">简单总结 <a class="header-anchor" href="#简单总结" aria-label="Permalink to “简单总结”">​</a></h3><ul><li>防抖： 停止触发后执行 ，适用于需要等待用户操作完成的场景</li><li>节流： 固定频率执行 ，适用于需要控制执行频率的场景</li></ul>',14)])])}const u=e(t,[["render",n]]);export{_ as __pageData,u as default};
